urlset:


  {{ site_url }}/
  {{ build_date }}
  daily
  1.0



{% for tool in tools %}
{% if tool.is_active %}

  {{ site_url }}/{{ tool.slug }}
  {{ build_date }}
  weekly
  0.9

{% endif %}
{% endfor %}


{% for cat in categories %}
{% if cat.is_active %}

  {{ site_url }}/{{ cat.slug }}
  {{ build_date }}
  weekly
  0.8

{% endif %}
{% endfor %}



  {{ site_url }}/blog
  {{ build_date }}
  weekly
  0.7

{% for post in posts %}
{% if post.status == 'published' %}

  {{ site_url }}/blog/{{ post.slug }}
  {{ post.published_at.strftime('%Y-%m-%d') if post.published_at else build_date }}
  monthly
  0.7

{% endif %}
{% endfor %}



  {{ site_url }}/about
  monthly
  0.3


  {{ site_url }}/privacy
  monthly
  0.3


  {{ site_url }}/terms
  monthly
  0.3


  {{ site_url }}/contact
  monthly
  0.3
